const levelNames=LEVELS.map(x=>x[0]);

/* UTILITÁRIOS E PREFERÊNCIAS */
function loadSettings(){try{const v=JSON.parse(localStorage.getItem('silentFalls'));if(v)settings={...settings,...v}}catch(e){}$('#crtOpt').value=settings.crt*100;$('#grainOpt').value=settings.grain*100;$('#ditherOpt').value=settings.dither*100;$('#volumeOpt').value=settings.volume*100;$('#moveOpt').value=settings.move}
function saveSettings(){try{localStorage.setItem('silentFalls',JSON.stringify(settings))}catch(e){}}
function makeMat(color,rough=.95,map=null){return new THREE.MeshStandardMaterial({color,roughness:rough,map,flatShading:true})}
function box(parent,x,y,z,w,h,d,mat){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);o.position.set(x,y,z);parent.add(o);return o}
function cylinder(parent,x,y,z,r1,r2,h,mat,seg=6){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);o.position.set(x,y,z);parent.add(o);return o}
function seeded(seed){let s=seed|0;return()=>{s=(s*1664525+1013904223)|0;return(s>>>0)/4294967296}}
/* GERADOR DE TEXTURAS PROCEDURAIS */
function texture(kind,seed=1){const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d'),r=seeded(seed);const palettes={wall:['#34403e','#5b625a','#222d2e'],tile:['#3b4744','#66706a','#222c2d'],rust:['#382b26','#744536','#a06a48'],cloth:['#393d3b','#73736b','#252a2a'],flesh:['#77756d','#a49a87','#514c48'],wood:['#392e29','#685144','#241f1c'],water:['#172b2d','#335052','#101a1b']};const p=palettes[kind]||palettes.wall;x.fillStyle=p[0];x.fillRect(0,0,64,64);for(let i=0;i<380;i++){x.globalAlpha=.22+r()*.55;x.fillStyle=p[Math.floor(r()*p.length)];const w=1+r()*12,h=1+r()*8;x.fillRect(r()*64,r()*64,w,h)}if(kind==='tile'){x.globalAlpha=.65;x.strokeStyle='#151d1d';x.lineWidth=2;for(let i=0;i<64;i+=16){x.beginPath();x.moveTo(i,0);x.lineTo(i,64);x.moveTo(0,i);x.lineTo(64,i);x.stroke()}}if(kind==='rust'||kind==='flesh'){for(let i=0;i<7;i++){x.globalAlpha=.2;x.fillStyle='#160f10';x.beginPath();x.ellipse(r()*64,r()*64,2+r()*10,1+r()*5,r()*3,0,7);x.fill()}}x.globalAlpha=1;const t=new THREE.CanvasTexture(c);t.magFilter=THREE.NearestFilter;t.minFilter=THREE.NearestFilter;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.generateMipmaps=false;return t}
const TEX={wall:texture('wall',4),tile:texture('tile',8),rust:texture('rust',12),cloth:texture('cloth',22),flesh:texture('flesh',3),wood:texture('wood',14),water:texture('water',19)};
/* SHADERS / PÓS-PROCESSAMENTO PS1 */
const vertexSnap=`#include <project_vertex>\nvec4 clipPos = projectionMatrix * mvPosition;\nvec2 snap = vec2(320.0,240.0);\nclipPos.xy = floor((clipPos.xy/clipPos.w)*snap*0.5+0.5)/snap*2.0*clipPos.w-clipPos.w;\ngl_Position=clipPos;`;
function retroMaterial(m){m.onBeforeCompile=s=>{s.vertexShader=s.vertexShader.replace('#include <project_vertex>',vertexSnap)};return m}
function makePost(){postScene=new THREE.Scene();postCamera=new THREE.OrthographicCamera(-1,1,1,-1,0,1);postMat=new THREE.ShaderMaterial({uniforms:{tDiffuse:{value:rt.texture},uTime:{value:0},uCRT:{value:settings.crt},uGrain:{value:settings.grain},uDither:{value:settings.dither},uDamage:{value:0}},vertexShader:'varying vec2 vUv; void main(){vUv=uv;gl_Position=vec4(position,1.);}',fragmentShader:`uniform sampler2D tDiffuse; uniform float uTime,uCRT,uGrain,uDither,uDamage; varying vec2 vUv; float bayer(vec2 p){int x=int(mod(p.x,4.)),y=int(mod(p.y,4.));int i=x+y*4;float a[16];a[0]=0.;a[1]=8.;a[2]=2.;a[3]=10.;a[4]=12.;a[5]=4.;a[6]=14.;a[7]=6.;a[8]=3.;a[9]=11.;a[10]=1.;a[11]=9.;a[12]=15.;a[13]=7.;a[14]=13.;a[15]=5.;return a[i]/16.-.5;} void main(){vec2 uv=vUv;vec2 p=uv*2.-1.;float curve=dot(p,p);uv+=p*curve*.035*uCRT;float ca=.0015*uCRT*curve;vec3 col=vec3(texture2D(tDiffuse,uv+vec2(ca,0.)).r,texture2D(tDiffuse,uv).g,texture2D(tDiffuse,uv-vec2(ca,0.)).b);float d=bayer(gl_FragCoord.xy)*.032*uDither;col=floor((col+d)*31.)/31.;float n=fract(sin(dot(gl_FragCoord.xy+uTime*73.,vec2(12.9898,78.233)))*43758.5453)-.5;col+=n*.075*uGrain;float scan=.94+.06*sin(gl_FragCoord.y*3.14159);float vig=1.-smoothstep(.35,1.5,dot(p,p)*.68)*.7*uCRT;float flick=.985+.015*sin(uTime*17.);col*=scan*vig*flick;col=mix(col,col*vec3(1.28,.45,.43),uDamage*.45);gl_FragColor=vec4(col,1.);}`});const q=new THREE.Mesh(new THREE.PlaneGeometry(2,2),postMat);postScene.add(q)}
/* ÁUDIO PROCEDURAL */
class Soundscape{constructor(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=settings.volume*.45;this.master.connect(this.ctx.destination);this.amb=this.ctx.createGain();this.amb.gain.value=.18;this.amb.connect(this.master);const osc=this.ctx.createOscillator(),low=this.ctx.createBiquadFilter();osc.type='triangle';osc.frequency.value=43;low.type='lowpass';low.frequency.value=150;osc.connect(low);low.connect(this.amb);osc.start();const buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const noise=this.ctx.createBufferSource();noise.buffer=buffer;noise.loop=true;const filt=this.ctx.createBiquadFilter();filt.type='lowpass';filt.frequency.value=360;const ng=this.ctx.createGain();ng.gain.value=.11;noise.connect(filt);filt.connect(ng);ng.connect(this.amb);noise.start();this.tension=this.ctx.createOscillator();this.tension.type='sawtooth';this.tension.frequency.value=59;this.tg=this.ctx.createGain();this.tg.gain.value=0;this.tension.connect(this.tg);this.tg.connect(this.master);this.tension.start()}
resume(){if(this.ctx&&this.ctx.state==='suspended')this.ctx.resume()}
setTension(v){if(this.tg)this.tg.gain.setTargetAtTime(v*.055,this.ctx.currentTime,.5)}
beep(f=120,d=.12,type='square',vol=.12){if(!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(f,this.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(25,f*.42),this.ctx.currentTime+d);g.gain.setValueAtTime(vol,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+d);o.connect(g);g.connect(this.master);o.start();o.stop(this.ctx.currentTime+d)}
shot(){this.beep(105,.22,'sawtooth',.25);this.beep(44,.24,'triangle',.2)}step(){this.beep(58+Math.random()*28,.07,'triangle',.035)}monster(){this.beep(70+Math.random()*35,.4,'sawtooth',.09)}hurt(){this.beep(90,.32,'sawtooth',.2)}
}
function initAudio(){if(!audio)audio=new Soundscape();audio.resume()}
</script>
</body>

