function initAudio(){if(!audio)audio=new Soundscape()}
/* MODELOS: protagonista, criaturas e cenário */
const world=new THREE.Group();let flashlight,ambientLights=[],roomObjects=[],roomSeed=1;
function makeHero(){const g=new THREE.Group();const coat=retroMaterial(makeMat(0x171b1c,.96,TEX.cloth)),skin=retroMaterial(makeMat(0xc4b4a9,.9,TEX.flesh)),hair=retroMaterial(makeMat(0x111315,.96,TEX.wood)),skirt=retroMaterial(makeMat(0x202426,.9,TEX.cloth)),boot=makeMat(0x101213),metal=makeMat(0x77736a);cylinder(g,0,.98,0,.35,.28,.7,coat,7);cylinder(g,0,.57,0,.37,.31,.32,skirt,7);const head=new THREE.Mesh(new THREE.IcosahedronGeometry(.22,1),skin);head.position.set(0,1.58,0);g.add(head);const haircap=new THREE.Mesh(new THREE.IcosahedronGeometry(.25,1),hair);haircap.position.set(0,1.7,-.02);g.add(haircap);for(let i=0;i<7;i++){const strand=new THREE.Mesh(new THREE.BoxGeometry(.09,.65,.1),hair);strand.position.set(rand(-.2,.2),1.35,rand(-.16,.16));strand.rotation.z=rand(-.45,.45);g.add(strand)}for(let side of [-1,1]){const arm=cylinder(g,side*.4,1.03,0,.11,.08,.56,coat,5);arm.rotation.z=side*-.22;const leg=cylinder(g,side*.16,.28,0,.12,.1,.48,coat,5);const b=box(g,side*.16,.08,.05,.22,.16,.34,boot);for(let j=0;j<2;j++)box(g,side*.16,.27+j*.08,.11,.16,.025,.025,metal)}const choker=cylinder(g,0,1.42,0,.23,.23,.045,boot,8);g.userData={head,arms:g.children.filter((o,i)=>i>0&&i<6),step:0};return g}
function makeMonster(type){const g=new THREE.Group();const bodyMat=type===2?retroMaterial(makeMat(0x514337,.95,TEX.rust)):retroMaterial(makeMat(type===0?0x77746b:type===1?0x545754:0x302d35,.98,type===1?TEX.cloth:TEX.flesh));const metal=retroMaterial(makeMat(0x66584a,.9,TEX.rust));const head=type===2?new THREE.Mesh(new THREE.IcosahedronGeometry(.39,1),metal):new THREE.Mesh(new THREE.IcosahedronGeometry(type===3?.34:.27,1),bodyMat);head.position.y=type===0?.68:1.55;g.add(head);if(type===0){const torso=new THREE.Mesh(new THREE.IcosahedronGeometry(.39,0),bodyMat);torso.scale.set(1.3,.65,.75);torso.position.set(0,.52,0);g.add(torso)}else{cylinder(g,0,1.02,0,type===2?.37:.25,type===2?.3:.22,type===2?1.05:.92,bodyMat,6)}for(let s of [-1,1]){for(let j=0;j<2;j++){const limb=cylinder(g,s*(type===0?.35:.3),type===0?.36:.74, j===0?-.2:.2,.09,.07,type===0?.75:.62,bodyMat,5);limb.rotation.z=s*(j===0?.7:-.55);if(type===3){const extra=cylinder(g,s*.48,1.15,j*.16,.06,.04,.62,bodyMat,5);extra.rotation.z=s*.65}}const eye=makeMat(type===2?0xa13d28:0x211c1c);for(let s of [-1,1]){const e=new THREE.Mesh(new THREE.SphereGeometry(.045,5,4),eye);e.position.set(s*.1,type===0?.72:1.57,.22);g.add(e)}if(type===0){const mouth=box(g,0,.63,.36,.19,.035,.025,makeMat(0x25201e));for(let i=0;i<4;i++)box(g,-.07+i*.045,.63,.38,.012,.08,.014,makeMat(0xb7aa9c))}if(type===2){const bar=cylinder(g,.54,.42,.18,.045,.045,1.3,metal,5);bar.rotation.z=1.1}g.userData={type,hp:[36,48,90,66][type],state:'idle',attack:rand(1,3),stun:0,phase:rand(0,6),speed:[.75,.9,.52,1.05][type]};return g}
const hero=makeHero();
/* GERADOR DE NÍVEIS: mapas em grade e geometria */
function clearRoom(){while(world.children.length)world.remove(world.children[0]);walls=[];props=[];items=[];enemies=[];ambientLights=[];roomObjects=[]}
