function reload(){if(gameState!=='playing'||player.reload>0||player.ammo>=8||player.reserve<=0)return;player.reload=1.05;audio?.beep(190,.08,'square',.06)}
function shoot(){if(gameState!=='playing'||player.reload>0||performance.now()-lastShot<360)return;if(player.ammo<=0){reload();audio?.beep(70,.08,'square',.08);return}lastShot=performance.now();player.ammo--;audio?.shot();const dir=new THREE.Vector3();camera.getWorldDirection(dir);raycaster.set(camera.position,dir);const candidates=[];for(const mob of enemies)if(mob.userData.hp>0)candidates.push(mob);const hits=raycaster.intersectObjects(candidates,true);if(hits.length){const mob=enemies.find(m=>m.userData.hp>0&&(m===hits[0].object||m.getObjectById(hits[0].object.id)));if(mob){mob.userData.hp-=34;if(mob.userData.hp<=0){mob.userData.hp=0;mob.userData.state='dead';totalKills++;if(Math.random()<CONFIG_DIFICULDADE[difficulty].ammoDrop)player.reserve+=4;audio?.beep(65,.3,'sawtooth',.16)}else{mob.userData.stun=.38;audio?.beep(115,.08,'square',.1)}}}updateHud()}
function damage(amount){if(player.invuln>0||gameState!=='playing')return;player.hp=clamp(player.hp-amount*CONFIG_DIFICULDADE[difficulty].damage,0,100);player.invuln=.7;damageFlash=.35;shake=.28;audio?.hurt();updateHud();if(player.hp<=0)gameOver()}
function heal(){if(gameState!=='playing'||player.heals<=0||player.hp>=100)return;player.heals--;player.hp=Math.min(100,player.hp+CONFIG_DIFICULDADE[difficulty].heal);audio?.beep(520,.24,'sine',.13);updateHud()}
function movePlayer(dt){const f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),s=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);if(!f&&!s)return;const len=Math.hypot(f,s),speed=keys.ShiftLeft||keys.ShiftRight?4.6:2.8;const dx=(s*Math.cos(player.yaw)+f*Math.sin(player.yaw))*speed*dt/len,dz=(f*Math.cos(player.yaw)-s*Math.sin(player.yaw))*speed*dt/len;const nx=hero.position.x+dx,nz=hero.position.z+dz,blocked=(x,z)=>walls.some(w=>Math.abs(x-w.x)<w.w/2+.38&&Math.abs(z-w.z)<w.d/2+.38);if(!blocked(nx,hero.position.z))hero.position.x=nx;if(!blocked(hero.position.x,nz))hero.position.z=nz;hero.position.x=clamp(hero.position.x,-14.1,14.1);hero.position.z=clamp(hero.position.z,-12.1,12.1);hero.rotation.y=player.yaw;player.walk+=dt*10;hero.position.y=Math.abs(Math.sin(player.walk))*.035;if(performance.now()-soundStep>460){soundStep=performance.now();audio?.step()}}
function updateEnemies(dt){let nearest=99;for(const mob of enemies){const u=mob.userData;if(u.hp<=0){mob.rotation.z=THREE.MathUtils.damp(mob.rotation.z,-Math.PI/2,2,dt);continue}const dx=hero.position.x-mob.position.x,dz=hero.position.z-mob.position.z,d=Math.hypot(dx,dz);nearest=Math.min(nearest,d);if(u.stun>0){u.stun-=dt;continue}u.attack-=dt;if(d>1.25){const speed=u.speed*(1+level*.045)*CONFIG_DIFICULDADE[difficulty].speed,step=Math.min(d-1.05,speed*dt);mob.position.x+=dx/d*step;mob.position.z+=dz/d*step;mob.rotation.y=Math.atan2(dx,dz);u.phase+=dt*5;mob.position.y=Math.sin(u.phase)*.045}else if(u.attack<=0){u.attack=u.type===3?1.15:1.55;damage(u.type===2?18:u.type===0?9:12)}}audio?.setTension(clamp((5-nearest)/5,0,1))}
function updateCamera(dt){const target=new THREE.Vector3(hero.position.x,hero.position.y+1.15,hero.position.z),desired=new THREE.Vector3(hero.position.x-Math.sin(player.yaw)*5.4,hero.position.y+3.1,hero.position.z-Math.cos(player.yaw)*5.4);camera.position.lerp(desired,1-Math.exp(-dt*7));if(shake>0){camera.position.x+=rand(-shake,shake);camera.position.y+=rand(-shake,shake);shake=Math.max(0,shake-dt)}camera.lookAt(target)}
function updateGame(dt){if(gameState!=='playing')return;elapsed+=dt;if(player.invuln>0)player.invuln-=dt;if(player.reload>0){player.reload-=dt;if(player.reload<=0){const n=Math.min(8-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;updateHud()}}if(damageFlash>0)damageFlash=Math.max(0,damageFlash-dt);movePlayer(dt);updateEnemies(dt);const t=nearestTarget();if(t)showPrompt(t.type==='exit'?(player.hasKey?'[E] ABRIR A SAÍDA':'SAÍDA TRANCADA — PROCURE O ITEM'):`[E] ${t.type==='key'?t.label:t.type==='heal'?'PEGAR KIT MÉDICO':'PEGAR MUNIÇÃO'}`);else hidePrompt();updateCamera(dt);if(postMat)postMat.uniforms.uDamage.value=clamp(damageFlash*2,0,1)}
function animate(now){requestAnimationFrame(animate);if(!renderer)return;const dt=Math.min(.05,(now-lastFrame)/1000||0);lastFrame=now;if(gameState==='playing')updateGame(dt);for(const l of ambientLights)l.light.intensity=(.2+Math.sin(now*.0018+l.phase)*.08)*(1+Math.random()*.04);if(rt&&postMat){renderer.setRenderTarget(rt);renderer.render(scene,camera);renderer.setRenderTarget(null);postMat.uniforms.uTime.value=now*.001;renderer.render(postScene,postCamera)}else renderer.render(scene,camera)}
function setupPost(){if(!renderer)return;rt=new THREE.WebGLRenderTarget(Math.max(320,innerWidth*.72|0),Math.max(180,innerHeight*.72|0),{minFilter:THREE.NearestFilter,magFilter:THREE.NearestFilter,format:THREE.RGBAFormat});makePost()}

