const CONFIG_DIFICULDADE={facil:{nome:'Fácil',ammo:40,enemyHp:1,damage:.7,speed:.78,ammoDrop:.8,healsPerLevel:3,heal:60,count:[2,6],passive:true},normal:{nome:'Normal',ammo:24,enemyHp:1,damage:1,speed:1,ammoDrop:.45,healsPerLevel:1,heal:40,count:[4,10],passive:false},dificil:{nome:'Difícil',ammo:14,enemyHp:2.2,damage:1.5,speed:1.35,ammoDrop:.12,healsPerLevel:0,heal:30,count:[4,10],passive:false}};

