 function updateEnemies(dt){let nearest=99;for(const mob of enemies){const u=mob.userData;if(u.hp<=0){mob.rotation.z=THREE.MathUtils.damp(mob.rotation.z,-Math.PI/2,2,dt);continue}const dx=hero.position.x-mob.position.x,dz=hero.position.z-mob.position.z,d=Math.hypot(dx,dz);nearest=Math.min(nearest,d);if(u.stun>0){u.stun-=dt;continue}u.attack-=dt;if(d>1.25){const speed=u.speed*(1+level*.045)*CONFIG_DIFICULDADE[difficulty].speed,step=Math.min(d-1.05,speed*dt);mob.position.x+=dx/d*step;mob.position.z+=dz/d*step;mob.rotation.y=Math.atan2(dx,dz);u.phase+=dt*5;mob.position.y=Math.sin(u.phase)*.045}else if(u.attack<=0){u.attack=u.type===3?1.15:1.55;damage(u.type===2?18:u.type===0?9:12)}}audio?.setTension(clamp((5-nearest)/5,0,1))}
 function updateCamera(dt){const target=new THREE.Vector3(hero.position.x,hero.position.y+1.15,hero.position.z),dist=cameraMode?2.1:5.4,height=cameraMode?1.95:3.1,desired=new THREE.Vector3(hero.position.x-Math.sin(player.yaw)*dist,hero.position.y+height,hero.position.z-Math.cos(player.yaw)*dist);camera.position.lerp(desired,1-Math.exp(-dt*7));if(shake>0){camera.position.x+=rand(-shake,shake);camera.position.y+=rand(-shake,shake);shake=Math.max(0,shake-dt)}camera.lookAt(target)}
