 function animate(now){requestAnimationFrame(animate);if(!renderer)return;const dt=Math.min(.05,(now-lastFrame)/1000||0);lastFrame=now;if(gameState==='playing')updateGame(dt);for(const l of ambientLights)l.light.intensity=(.2+Math.sin(now*.0018+l.phase)*.08)*(1+Math.random()*.04);if(rt&&postMat){renderer.setRenderTarget(rt);renderer.render(scene,camera);renderer.setRenderTarget(null);postMat.uniforms.uTime.value=now*.001;renderer.render(postScene,postCamera)}else renderer.render(scene,camera)}

